describe('Modal Responsive on Mobile Screen Sizes', () => {
  beforeEach(() => {
    cy.visit('/modal');
  });

  it('should display modal responsively on mobile devices', () => {
    // Set viewport to mobile size
    cy.viewport('iphone-x');

    // Verify modal is visible and has correct dimensions
    cy.get('[data-testid="modal-container"]').should('be.visible');
    cy.get('[data-testid="modal-container"]').should('have.css', 'width', '375px');
    cy.get('[data-testid="modal-container"]').should('have.css', 'height', '812px');

    // Verify modal content is readable
    cy.get('[data-testid="modal-title"]').should('contain', 'Modal Title');
    cy.get('[data-testid="modal-body"]').should('contain', 'Modal body content');

    // Verify close button is present and functional
    cy.get('[data-testid="modal-close-btn"]').should('be.visible');
    cy.get('[data-testid="modal-close-btn"]').click();
    cy.get('[data-testid="modal-container"]').should('not.exist');
  });

  it('should handle modal overflow on very small screens', () => {
    // Set viewport to extremely small size
    cy.viewport('iphone-xs');

    // Verify modal is still visible and does not overflow
    cy.get('[data-testid="modal-container"]').should('be.visible');
    cy.get('[data-testid="modal-container"]').should('have.css', 'width', '320px');
    cy.get('[data-testid="modal-container"]').should('have.css', 'height', '800px');

    // Verify modal content is still readable
    cy.get('[data-testid="modal-title"]').should('contain', 'Modal Title');
    cy.get('[data-testid="modal-body"]').should('contain', 'Modal body content');

    // Verify scrollable overflow is handled
    cy.get('[data-testid="modal-body"]').should('be.visible');
    cy.get('[data-testid="modal-body"]').scrollTo('bottom');
    cy.get('[data-testid="modal-body"]').should('have.scrollHeight', '> 800px');

    // Verify close button is still functional
    cy.get('[data-testid="modal-close-btn"]').click();
    cy.get('[data-testid="modal-container"]').should('not.exist');
  });
});
